func TestRerankerValidatedIndicesPythonParity(t *testing.T) {
	for _, tc := range rerankerIndicesParityCases {
		got := validatedIndices(tc.results, tc.candidateCount)
		if !reflect.DeepEqual(got, tc.want) {
			t.Errorf("%s: got %#v want %#v", tc.name, got, tc.want)
		}
	}
}

func TestRerankerProjectTextPythonParity(t *testing.T) {
	for _, tc := range rerankerProjectTextParityCases {
		got := projectText(tc.project)
		if got != tc.want {
			t.Errorf("%s: got %q want %q", tc.name, got, tc.want)
		}
	}
}

func TestSemanticRRFPythonParity(t *testing.T) {
	got := ReciprocalRankFusion(semanticRRFParityRankings, 60, 200)
	if len(got) != len(semanticRRFParityWant) {
		t.Fatalf("got %d hits want %d", len(got), len(semanticRRFParityWant))
	}
	for i := range got {
		if got[i].RepoID != semanticRRFParityWant[i].RepoID || math.Abs(got[i].Score-semanticRRFParityWant[i].Score) > 1e-15 {
			t.Errorf("%d: got %#v want %#v", i, got[i], semanticRRFParityWant[i])
		}
	}
}
